const search=document.getElementById('library-search');search.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();let shown=0;document.querySelectorAll('.library-branch').forEach(card=>{card.hidden=!card.dataset.search.includes(q);if(!card.hidden)shown++});document.getElementById('library-count').textContent=`${shown} of 7 branches`;document.getElementById('library-empty').hidden=shown>0;});